begin;set search_path to public,extensions;select plan(33);
insert into auth.users(id,email)values('b0000000-0000-4000-8000-000000000001','messaging-tenant@example.test'),('b0000000-0000-4000-8000-000000000002','messaging-representative@example.test'),('b0000000-0000-4000-8000-000000000003','messaging-outsider@example.test');
insert into private.administrator_grants(user_id,reason)values('b0000000-0000-4000-8000-000000000003','Synthetic messaging administrator');
insert into public.properties(id,name,address,state,city,locality,property_type,rent_min,rent_max)values('b1000000-0000-4000-8000-000000000001','Synthetic contact property','Synthetic messaging lane','Delhi','Messaging fixture city','Fixture area','Flat',1000,2000);
insert into private.documents(id,owner_id,object_path)values('b2000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000002','claim/b2000000-0000-4000-8000-000000000001.jpg');
insert into private.claims(id,user_id,property_id,document_id,status)values('b3000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','approved');
create temp table messaging_profile as select public_profile_id from private.accounts where user_id='b0000000-0000-4000-8000-000000000002';grant select on messaging_profile to authenticated;
set local role anon;
select throws_ok($$select get_my_conversations()$$,'42501',null,'Anonymous threads denied');
select throws_ok($$select set_contact_preference(true)$$,'42501',null,'Anonymous opt-in denied');
set local role authenticated;select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),0,'Representative defaults to opt out');
select throws_ok($$select start_conversation('b1000000-0000-4000-8000-000000000001',(select public_profile_id from messaging_profile),true)$$,'42501',null,'Cannot bypass representative consent');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000002',true);select set_contact_preference(true);
select is(get_contact_preference(),true,'Own opt-in saved');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),1,'Approved opt-in visible');
select throws_ok($$select start_conversation('b1000000-0000-4000-8000-000000000001',(select public_profile_id from messaging_profile),false)$$,'42501',null,'Tenant must consent');
select start_conversation('b1000000-0000-4000-8000-000000000001',(select public_profile_id from messaging_profile),true);
reset role;create temp table messaging_thread as select id from private.conversations where property_id='b1000000-0000-4000-8000-000000000001';grant select on messaging_thread to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select is(start_conversation('b1000000-0000-4000-8000-000000000001',(select public_profile_id from messaging_profile),true),(select id from messaging_thread),'Duplicate start returns same thread');
select send_message((select id from messaging_thread),'Synthetic private tenant message');
select is(jsonb_array_length(get_conversation_messages((select id from messaging_thread))),1,'Participant reads message');
select ok(not(get_my_conversations()->0 ? 'tenant_id'),'DTO omits auth identity');
select throws_ok($$select send_message((select id from messaging_thread),'')$$,'P0001','Use 1–2000 characters','Empty message rejected');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000003',true);
select is(jsonb_array_length(get_my_conversations()),0,'Even admin cannot list foreign conversations');
select throws_ok($$select get_conversation_messages((select id from messaging_thread))$$,'42501',null,'Even admin cannot read unreported message');
select throws_ok($$select send_message((select id from messaging_thread),'Forged sender')$$,'42501',null,'Outsider cannot send');
select throws_ok($$select set_conversation_block((select id from messaging_thread),true)$$,'42501',null,'Outsider cannot block');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(get_my_notifications()),1,'Generic private message notification');
select report_message((get_conversation_messages((select id from messaging_thread))->0->>'id')::uuid,'Synthetic message report reason');
select set_conversation_block((select id from messaging_thread),true);
select throws_ok($$select send_message((select id from messaging_thread),'Blocked reply')$$,'42501',null,'Block stops both directions');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);select set_conversation_block((select id from messaging_thread),false);
select throws_ok($$select send_message((select id from messaging_thread),'Bypass other block')$$,'42501',null,'Cannot remove other participant block');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000002',true);select set_conversation_block((select id from messaging_thread),false);select set_contact_preference(false);
select throws_ok($$select send_message((select id from messaging_thread),'Opted out reply')$$,'42501',null,'Opt-out stops existing thread');select set_contact_preference(true);
select throws_ok($$select get_admin_message_reports()$$,'42501',null,'Ordinary report queue denied');
select throws_ok($$select set_property_location('b1000000-0000-4000-8000-000000000001',28,77,'approximate','Synthetic coordinate source')$$,'42501',null,'Ordinary coordinates denied');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000003',true);
select is(jsonb_array_length(get_admin_message_reports()),1,'Admin sees reported message only');
select decide_message_report((get_admin_message_reports()->0->>'id')::uuid,'removed','Synthetic message removal reason');
select lives_ok($$select set_property_location('b1000000-0000-4000-8000-000000000001',28,77,'approximate','Synthetic coordinate source')$$,'Audited coordinates accepted');
select throws_ok($$select set_property_location('b1000000-0000-4000-8000-000000000001',95,77,'exact','Synthetic invalid coordinate')$$,'23514',null,'Invalid latitude rejected');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select is(get_conversation_messages((select id from messaging_thread))->0->>'body','[Removed following moderation]','Removed body concealed');
reset role;update private.claims set status='revoked'where id='b3000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select send_message((select id from messaging_thread),'Revoked claim send')$$,'42501',null,'Claim revocation stops messaging');
reset role;
insert into public.landlords(id,name)values('b4000000-0000-4000-8000-000000000001','Synthetic contact manager');
insert into public.management_associations(id,property_id,landlord_id,start_date,active)values('b5000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001','2020-01-01',false);
update private.claims set status='approved',property_id=null,landlord_id='b4000000-0000-4000-8000-000000000001'where id='b3000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),0,'Inactive management cannot authorize contact');
reset role;update public.management_associations set active=true where id='b5000000-0000-4000-8000-000000000001';set local role authenticated;
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),1,'Current active manager claim permits contact');
reset role;update public.landlords set status='hidden'where id='b4000000-0000-4000-8000-000000000001';set local role authenticated;
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),0,'Hidden manager cannot authorize contact');
reset role;update public.landlords set status='published'where id='b4000000-0000-4000-8000-000000000001';update public.management_associations set end_date='2021-01-01'where id='b5000000-0000-4000-8000-000000000001';set local role authenticated;
select is(jsonb_array_length(get_contactable_representatives('b1000000-0000-4000-8000-000000000001')),0,'Historic manager cannot authorize new contact');
reset role;delete from auth.users where id='b0000000-0000-4000-8000-000000000001';
select is((select count(*)::int from private.conversations where id=(select id from messaging_thread)),0,'Account deletion erases conversation');
select is((select count(*)::int from private.messages where conversation_id=(select id from messaging_thread)),0,'Account deletion erases both participants messages');
select is((select count(*)::int from private.message_reports),0,'Account deletion erases private message report body');
select * from finish();rollback;
